#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 5;                           // 원소 0..4
    int mask = 0;
    mask |= 1 << 1;                      // 1번 켜기
    mask |= 1 << 3;                      // 3번 켜기
    cout << bitset<5>(mask) << ' ' << mask << '\n';

    cout << "3번 있음? " << ((mask >> 3) & 1) << '\n';
    cout << "2번 있음? " << ((mask >> 2) & 1) << '\n';

    mask ^= 1 << 0;                      // 0번 뒤집기(꺼져 있으면 켜기)
    mask &= ~(1 << 3);                   // 3번 끄기
    cout << bitset<5>(mask) << '\n';

    cout << "켜진 개수 " << __builtin_popcount(mask) << '\n';
    cout << "가장 낮은 켜진 비트 " << (mask & -mask) << '\n';
    int full = (1 << n) - 1;
    cout << "여집합 " << bitset<5>(mask ^ full) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<char> items = {'A', 'B', 'C'};
    vector<int> price = {3, 5, 4};
    int n = items.size();
    for (int mask = 0; mask < (1 << n); mask++) {   // 모든 부분집합
        string chosen;
        int total = 0;
        for (int i = 0; i < n; i++) {
            if ((mask >> i) & 1) {
                chosen += items[i];
                total += price[i];
            }
        }
        cout << bitset<3>(mask) << ' ' << (chosen.empty() ? "-" : chosen) << ' ' << total << '\n';
    }

    // mask 의 부분집합만 돌기: sub = (sub - 1) & mask
    int mask = 0b101;
    for (int sub = mask; sub; sub = (sub - 1) & mask) cout << bitset<3>(sub) << ' ';
    cout << "000\n";                     // 공집합은 따로
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    const int INF = 1e9;
    // cost[i][j]: i 에서 j 로 가는 비용 (0 이면 길 없음)
    vector<vector<int>> cost = {
        {0, 10, 15, 20},
        {5, 0, 9, 10},
        {6, 13, 0, 12},
        {8, 8, 9, 0},
    };
    int n = cost.size();
    int FULL = (1 << n) - 1;
    // dp[mask][v]: 0번에서 출발해 mask 의 도시를 모두 방문하고 지금 v 에 있을 때 최소 비용
    vector<vector<int>> dp(1 << n, vector<int>(n, INF));
    dp[1][0] = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        for (int v = 0; v < n; v++) {
            if (dp[mask][v] == INF) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if (((mask >> nxt) & 1) || cost[v][nxt] == 0) continue;
                int nmask = mask | (1 << nxt);
                dp[nmask][nxt] = min(dp[nmask][nxt], dp[mask][v] + cost[v][nxt]);
            }
        }
    }

    int ans = INF;
    for (int v = 1; v < n; v++)
        if (cost[v][0] && dp[FULL][v] < INF) ans = min(ans, dp[FULL][v] + cost[v][0]);
    cout << ans << '\n';
    return 0;
}
